      es: ["Se extiende sobre un área de unos 3 kilómetros cuadrados.", "Se inauguró oficialmente en la primera mitad de los años 70.", "Alberga la torre Al-Zawraa, de 55 metros de altura, terminada en 1999.", "El estadio integrado tiene una capacidad de 15.000 asientos.", "Tras los daños sufridos en la década de 2000, en 2008 comenzaron amplias renovaciones.", "En días festivos importantes, suele registrar más de 100.000 visitantes diarios."],
      pt: ["Estende-se por uma área de cerca de 3 quilômetros quadrados.", "Foi inaugurado oficialmente na primeira metade da década de 1970.", "Abriga a torre Al-Zawraa de 55 metros de altura, concluída em 1999.", "O estádio integrado tem uma capacidade de 15.000 lugares sentados.", "Após danos sofridos na década de 2000, renovações extensas começaram em 2008.", "Em feriados importantes, registra frequentemente mais de 100.000 visitantes por dia."],
      fr: ["S'étend sur une superficie d'environ 3 kilomètres carrés.", "A été officiellement inauguré dans la première moitié des années 1970.", "Abrite la tour Al-Zawraa, haute de 55 mètres et achevée en 1999.", "Le stade intégré dispose d'une capacité de 15 000 places assises.", "Après des dommages dans les années 2000, de vastes rénovations ont débuté en 2008.", "Enregistre souvent plus de 100 000 visiteurs par jour lors des grandes fêtes."],
