      de: ["Der Freizeitkomplex wurde 2011 mit einer Investition von 40 Millionen US-Dollar fertiggestellt.", "Die gesamte Parkanlage beansprucht ein Areal von 150.000 Quadratmetern.", "Das Hauptriesenrad erreicht eine strukturelle Höhe von 45 Metern.", "Auf dem Gelände befinden sich insgesamt 30 mechanische Fahrgeschäfte.", "Eine 5.000 Quadratmeter große Halle beherbergt Indoor-Aktivitäten und Arcade-Spiele.", "Die Parkplätze der Einrichtung bieten eine Kapazität für 800 Fahrzeuge."],
      hu: ["A szórakoztató központot 2011-ben, mintegy 40 millió amerikai dollárból építették fel.", "A teljes szabadidős létesítmény összesen 150 000 négyzetméteres területet foglal el.", "A fő attrakciónak számító óriáskerék szerkezeti magassága eléri a 45 métert.", "A komplexum területén összesen 30 különböző mechanikus szórakoztató elem található.", "A beltéri játékoknak és tevékenységeknek egy 5000 négyzetméteres csarnok ad otthont.", "A létesítmény saját gépjárműparkolója 800 autó befogadására lett méretezve."],
      ro: ["Complexul de agrement a fost finalizat în 2011 cu o investiție de 40 de milioane de dolari.", "Întregul parc ocupă o suprafață de 150.000 de metri pătrați.", "Roata panoramică principală atinge o înălțime structurală de 45 de metri.", "Pe amplasament se găsesc un total de 30 de atracții mecanice.", "O sală de 5.000 de metri pătrați găzduiește activități de interior și jocuri arcade.", "Parcările facilității oferă o capacitate totală pentru 800 de vehicule."],
      es: ["El complejo de ocio se completó en 2011 con una inversión de 40 millones de dólares.", "Todo el parque ocupa una superficie de 150.000 metros cuadrados.", "La noria principal alcanza una altura estructural de 45 metros.", "En el recinto hay un total de 30 atracciones mecánicas.", "Una sala de 5.000 metros cuadrados alberga actividades de interior y juegos arcade.", "Los aparcamientos de la instalación tienen capacidad para 800 vehículos."],
